  1 │ /**
  2 │  * Hash chain for append-only records (GV-3). Each record carries a link: its position, the hash of the record before
  3 │  * it, and its own hash over (position, previous hash, canonical content). Changing, removing or reordering a record
  4 │  * breaks every link after it, so the damage is found by reading the log, without a separate index.
  5 │  *
  6 │  * What a chain cannot show by itself: records removed from the END leave a shorter chain that is still consistent.
  7 │  * A log with a defined last record (a flight's `session_end`) reports whether it is closed; anything stronger needs
  8 │  * a copy of the head hash kept somewhere else (the signed audit export, GV-2).
  9 │  *
 10 │  * This is tamper evidence, not tamper proofing: someone who can rewrite the whole file can recompute every hash.
 11 │  */
 12 │ import { createHash } from "node:crypto";
 13 │ 
 14 │ export interface ChainLink {
 15 │   /** Position in the log, from 0. */
 16 │   seq: number;
 17 │   /** `hash` of the previous record; CHAIN_GENESIS for the first. */
 18 │   prev: string;
 19 │   /** SHA-256 over `${seq}\n${prev}\n${canonicalJson(record without its chain)}`, hex. */
 20 │   hash: string;
 21 │ }
 22 │ 
 23 │ export const CHAIN_GENESIS = "0".repeat(64);
 24 │ const HEX64 = /^[0-9a-f]{64}$/;
 25 │ 
 26 │ /**
 27 │  * JSON with object keys sorted at every depth, so a record hashes the same after it has been written and parsed
 28 │  * again. Follows JSON.stringify for everything else (undefined members dropped, non-finite numbers as null).
 29 │  */
 30 │ export function canonicalJson(value: unknown): string {
 31 │   if (value === null || typeof value !== "object") return JSON.stringify(value) ?? "null";
 32 │   if (Array.isArray(value)) return `[${value.map((item) => (item === undefined ? "null" : canonicalJson(item))).join(",")}]`;
 33 │   const toJson = (value as { toJSON?: () => unknown }).toJSON;
 34 │   if (typeof toJson === "function") return canonicalJson(toJson.call(value));
 35 │   const members: string[] = [];
 36 │   for (const key of Object.keys(value as Record<string, unknown>).sort()) {
 37 │     const member = (value as Record<string, unknown>)[key];
 38 │     if (member === undefined || typeof member === "function" || typeof member === "symbol") continue;
 39 │     members.push(`${JSON.stringify(key)}:${canonicalJson(member)}`);
 40 │   }
 41 │   return `{${members.join(",")}}`;
 42 │ }
 43 │ 
 44 │ function linkHash(seq: number, prev: string, content: unknown): string {
 45 │   return createHash("sha256").update(`${seq}\n${prev}\n${canonicalJson(content)}`, "utf8").digest("hex");
 46 │ }
 47 │ 
 48 │ function withoutChain(record: object): Record<string, unknown> {
 49 │   const { chain: _chain, ...content } = record as Record<string, unknown>;
 50 │   return content;
 51 │ }
 52 │ 
 53 │ /** The record with its link to `previous` (the link of the record before it; undefined for the first). */
 54 │ export function linkRecord<T extends object>(record: T, previous: ChainLink | undefined): T & { chain: ChainLink } {
 55 │   const seq = previous ? previous.seq + 1 : 0;
 56 │   const prev = previous ? previous.hash : CHAIN_GENESIS;
 57 │   return { ...record, chain: { seq, prev, hash: linkHash(seq, prev, withoutChain(record)) } };
 58 │ }
 59 │ 
 60 │ export type ChainProblem =
 61 │   /** The record's content does not match its hash: it was changed after it was written. */
 62 │   | "edited"
 63 │   /** The record does not follow the one before it: something was removed, inserted or reordered here. */
 64 │   | "out_of_order"
 65 │   /** A record without a link inside a chained log, or a line that is not a record at all. */
 66 │   | "unlinked";
 67 │ 
 68 │ export type ChainVerdict =
 69 │   /** Every record links to the one before it. `head` is the last link (absent for an empty log). */
 70 │   | { status: "intact"; records: number; head?: ChainLink }
 71 │   /** No record carries a link: written before chaining existed. Nothing can be said about its integrity. */
 72 │   | { status: "unchained"; records: number }
 73 │   /** The first record that fails, by position in the input. Records before it verified; nothing after it was trusted. */
 74 │   | { status: "broken"; records: number; at: number; problem: ChainProblem; detail: string };
 75 │ 
 76 │ function readLink(record: unknown): ChainLink | undefined {
 77 │   const chain = record && typeof record === "object" ? (record as { chain?: unknown }).chain : undefined;
 78 │   if (!chain || typeof chain !== "object") return undefined;
 79 │   const { seq, prev, hash } = chain as Record<string, unknown>;
 80 │   if (!Number.isSafeInteger(seq) || (seq as number) < 0 || typeof prev !== "string" || typeof hash !== "string") return undefined;
 81 │   if (!HEX64.test(prev) || !HEX64.test(hash)) return undefined;
 82 │   return { seq: seq as number, prev, hash };
 83 │ }
 84 │ 
 85 │ function hasChainField(record: unknown): boolean {
 86 │   return record !== null && typeof record === "object" && Object.prototype.hasOwnProperty.call(record, "chain");
 87 │ }
 88 │ 
 89 │ /**
 90 │  * Check a log read back from disk. `records` are the parsed records in file order; pass `null` for a line that could
 91 │  * not be parsed, so it is reported at its position instead of being skipped.
 92 │  */
 93 │ export function verifyChain(records: ReadonlyArray<unknown>): ChainVerdict {
 94 │   const total = records.length;
 95 │   if (total === 0) return { status: "intact", records: 0 };
 96 │   if (records.every((record) => record !== null && readLink(record) === undefined && !hasChainField(record))) {
 97 │     return { status: "unchained", records: total };
 98 │   }
 99 │   let previous: ChainLink | undefined;
100 │   for (let at = 0; at < total; at++) {
101 │     const record = records[at];
102 │     const link = readLink(record);
103 │     if (!link) {
104 │       const detail = record === null
105 │         ? "this line is not a readable record"
106 │         : hasChainField(record)
107 │           ? "this record has a malformed chain link"
108 │           : "this record has no chain link, but the log is chained";
109 │       return { status: "broken", records: total, at, problem: "unlinked", detail };
110 │     }
111 │     const expectedSeq = previous ? previous.seq + 1 : 0;
112 │     const expectedPrev = previous ? previous.hash : CHAIN_GENESIS;
113 │     if (link.seq !== expectedSeq || link.prev !== expectedPrev) {
114 │       const detail = link.seq !== expectedSeq
115 │         ? `expected record ${expectedSeq} here, found record ${link.seq}`
116 │         : `record ${link.seq} does not follow the record before it`;
117 │       return { status: "broken", records: total, at, problem: "out_of_order", detail };
118 │     }
119 │     if (linkHash(link.seq, link.prev, withoutChain(record as object)) !== link.hash) {
120 │       return { status: "broken", records: total, at, problem: "edited", detail: `record ${link.seq} was changed after it was written` };
121 │     }
122 │     previous = link;
123 │   }
124 │   return { status: "intact", records: total, head: previous };
125 │ }
126 │ 
127 │ /** One line an operator can read. */
128 │ export function describeChain(verdict: ChainVerdict): string {
129 │   switch (verdict.status) {
130 │     case "intact":
131 │       return verdict.records === 0 ? "empty" : `chain intact (${verdict.records} record${verdict.records === 1 ? "" : "s"})`;
132 │     case "unchained":
133 │       return `not chained (${verdict.records} record${verdict.records === 1 ? "" : "s"} written before hash chaining; integrity cannot be checked)`;
134 │     case "broken":
135 │       return `CHAIN BROKEN at position ${verdict.at + 1} of ${verdict.records}: ${verdict.detail}`;
136 │   }
137 │ }
  1 │ /**
  2 │  * Session export (`/export` in the TUI and the REPL). The export carries the authoritative task state — objective,
  3 │  * requirement states, steering, verifier attempts, plan, milestones, receipts, last turn — beside the conversation,
  4 │  * and says plainly whether the conversation is the full history or a compacted context whose earlier messages were
  5 │  * replaced by summaries (the replaced originals are included from the session's archive when it exists).
  6 │  */
  7 │ import type { SessionData, SessionManager } from "./session.js";
  8 │ import { safeOperatorText } from "./protocol.js";
  9 │ import type { ChatMessage } from "./types.js";
 10 │ import { gatingRequirements, requirementDone } from "./core/objective.js";
 11 │ import { describeChain, verifyChain } from "./core/hash_chain.js";
 12 │ 
 13 │ export const EXPORT_FORMAT = "nexus-session-export/2";
 14 │ const SUMMARY_PREFIX = "[Structured Context Memory";
 15 │ 
 16 │ export interface HistoryCompleteness {
 17 │   complete: boolean | "unknown";
 18 │   compactions: number;
 19 │   archivedMessages: number;
 20 │   archivedIncluded: number;
 21 │   unreadableArchiveLines: number;
 22 │   summaryMessagesInContext: number;
 23 │   note: string;
 24 │ }
 25 │ 
 26 │ function contentText(message: ChatMessage): string {
 27 │   return typeof message.content === "string" ? message.content : JSON.stringify(message.content ?? "");
 28 │ }
 29 │ 
 30 │ export function historyCompleteness(session: SessionData, archived: { messages: ChatMessage[]; unreadableLines: number }): HistoryCompleteness {
 31 │   const summaries = session.messages.filter((m, i) => i > 0 && m.role === "system" && contentText(m).startsWith(SUMMARY_PREFIX)).length;
 32 │   const recorded = session.history;
 33 │   const compactions = recorded?.compactions ?? (summaries > 0 ? summaries : 0);
 34 │   const compacted = compactions > 0 || summaries > 0;
 35 │   const complete: HistoryCompleteness["complete"] = recorded ? !compacted : compacted ? false : "unknown";
 36 │   const archivedMessages = recorded?.archivedMessages ?? 0;
 37 │   let note: string;
 38 │   if (!compacted) {
 39 │     note = recorded ? "The conversation below is the full history of this session." : "This session predates history tracking; no compaction summary is present in its context.";
 40 │   } else if (archived.messages.length > 0 && archived.messages.length >= archivedMessages && archived.unreadableLines === 0) {
 41 │     note = `Context compaction replaced earlier messages with summaries ${compactions} time(s); the ${archived.messages.length} replaced originals are included under archivedHistory, so together they are the full history.`;
 42 │   } else {
 43 │     note =
 44 │       `Context compaction replaced earlier messages with summaries ${compactions} time(s). ` +
 45 │       `${archived.messages.length} of ${archivedMessages || "an unknown number of"} replaced originals are available in the archive` +
 46 │       `${archived.unreadableLines ? ` (${archived.unreadableLines} unreadable line(s))` : ""}; the rest exist only as the summaries in the context below. This export is NOT the full history.`;
 47 │   }
 48 │   return {
 49 │     complete,
 50 │     compactions,
 51 │     archivedMessages,
 52 │     archivedIncluded: archived.messages.length,
 53 │     unreadableArchiveLines: archived.unreadableLines,
 54 │     summaryMessagesInContext: summaries,
 55 │     note,
 56 │   };
 57 │ }
 58 │ 
 59 │ export interface SessionExport {
 60 │   json: Record<string, unknown>;
 61 │   markdown: string;
 62 │ }
 63 │ 
 64 │ /** Each requirement evidence item with who produced it; an item nothing records as tool output is the model's claim. */
 65 │ export function evidenceProvenance(objective: SessionData["objective"] | null | undefined): { requirement: string; evidence: string; source: "tool" | "model" }[] {
 66 │   return (objective?.requirements ?? []).flatMap((r) => r.evidence.map((evidence) => ({ requirement: r.id, evidence, source: r.evidenceSources?.[evidence] ?? ("model" as const) })));
 67 │ }
 68 │ 
 69 │ export function buildSessionExport(manager: SessionManager, session: SessionData): SessionExport {
 70 │   let archived: { messages: ChatMessage[]; unreadableLines: number } = { messages: [], unreadableLines: 0 };
 71 │   try {
 72 │     archived = manager.readArchivedHistory(session.id);
 73 │   } catch {}
 74 │   const history = historyCompleteness(session, archived);
 75 │   const objective = session.objective ?? null;
 76 │   const lastTurn = session.lastTurn ?? null;
 77 │   const json: Record<string, unknown> = {
 78 │     ...session,
 79 │     export: {
 80 │       format: EXPORT_FORMAT,
 81 │       exportedAt: new Date().toISOString(),
 82 │       history,
 83 │       taskState: {
 84 │         status: session.status,
 85 │         outcome: lastTurn ? { execution: lastTurn.execution, outcome: lastTurn.outcome, reason: lastTurn.reason ?? null, detail: lastTurn.detail ?? null } : null,
 86 │         objectiveOutcome: objective?.outcome ?? null,
 87 │         unresolvedRequirements: objective ? gatingRequirements(objective).filter((r) => !requirementDone(r)) : [],
 88 │         steering: objective?.steering ?? [],
 89 │         steeringConflicts: objective?.steeringConflicts ?? [],
 90 │         supersededObjectives: objective?.superseded ?? [],
 91 │         evidenceProvenance: evidenceProvenance(objective),
 92 │         verificationAttempts: objective?.verification ?? [],
 93 │         verificationEvidence: lastTurn?.verification ?? null,
 94 │         verificationConfigAttempts: session.verificationConfigAttempts ?? [],
 95 │         commandRuleDecisions: session.commandRuleDecisions ?? [],
 96 │         unverifiedChangesPending: session.unverifiedChangesPending ?? null,
 97 │       },
 98 │       tokenAccounting:
 99 │         "tokenStats.prompt sums the input tokens of every inference request; each request re-sends the whole context, so it grows " +
100 │         "with steps x context size. reportedRequests came from provider usage reports, estimatedRequests were estimated locally.",
101 │     },
102 │     archivedHistory: archived.messages,
103 │   };
104 │   return { json, markdown: markdownExport(session, history, archived.messages) };
105 │ }
106 │ 
107 │ /**
108 │  * Escape a value for a Markdown table cell. Newlines are normalized to spaces first so they
109 │  * cannot terminate the table row; backslashes are escaped next, then pipes, so an existing
110 │  * backslash (e.g. from `\|` in the source) cannot neutralise the pipe escape and break the
111 │  * surrounding table row (CodeQL js/incomplete-sanitization).
112 │  */
113 │ export function escapeTableCell(value: string): string {
114 │   return value
115 │     .replace(/\r\n|\r|\n/g, " ")
116 │     .replace(/\\/g, "\\\\")
117 │     .replace(/\|/g, "\\|");
118 │ }
119 │ 
120 │ function markdownExport(session: SessionData, history: HistoryCompleteness, archived: ChatMessage[]): string {
121 │   const out: string[] = [
122 │     "# Nexus Code Session Export",
123 │     "",
124 │     `- **Session ID:** \`${session.id}\``,
125 │     `- **Workspace:** \`${session.workspace}\``,
126 │     `- **Date:** ${session.createdAt}`,
127 │     `- **Model:** \`${session.model}\``,
128 │     `- **Status:** ${session.status}`,
129 │   ];
130 │   const t = session.lastTurn;
131 │   if (t) out.push(`- **Last turn:** execution=${t.execution} outcome=${t.outcome}${t.reason ? ` reason=${t.reason}` : ""}${t.detail ? ` (${t.detail})` : ""}`);
132 │   out.push("", `> **History:** ${history.note}`, "");
133 │   const objective = session.objective;
134 │   if (objective) {
135 │     out.push("## Objective", "", "```text", objective.objective, "```", "");
136 │     const gating = gatingRequirements(objective);
137 │     if (gating.length) {
138 │       out.push("| Requirement | Status | Evidence / note |", "|---|---|---|");
139 │       for (const r of gating) out.push(`| ${escapeTableCell(r.id)} ${escapeTableCell(r.text)} | ${escapeTableCell(r.status)} | ${escapeTableCell([...r.evidence.map((e) => `[${r.evidenceSources?.[e] ?? "model"}] ${e}`), r.note ?? ""].filter(Boolean).join("; "))} |`);
140 │       out.push("");
141 │     }
142 │     if (objective.outcome) {
143 │       const o = objective.outcome;
144 │       out.push(`**Objective outcome:** ${o.status} (${o.reason})${o.failedCheck ? ` — failed check: ${o.failedCheck}` : ""}${o.nextAction ? ` — next: ${o.nextAction}` : ""}`, "");
145 │     }
146 │     if (objective.steering.length) {
147 │       out.push("**Operator steering:**", "");
148 │       for (const s of objective.steering) out.push(`- ${s.id} [${s.status}${s.appliedAtStep ? ` at step ${s.appliedAtStep}` : ""}] ${s.text}`);
149 │       out.push("");
150 │     }
151 │     if (objective.steeringConflicts?.length) {
152 │       out.push("**Steering conflicts (negated requirements):**", "");
153 │       for (const c of objective.steeringConflicts) out.push(`- ${c.id} [${c.status}] negates ${c.requirements.join(", ")}: ${safeOperatorText(c.text)}`);
154 │       out.push("");
155 │     }
156 │     if (objective.superseded?.length) {
157 │       out.push("**Requirements left unmet by a replaced objective:**", "");
158 │       for (const o of objective.superseded) out.push(`- [${o.status}] ${o.requirements.map((r) => `${r.id} (${r.status}) ${r.text}`).join("; ")}`);
159 │       out.push("");
160 │     }
161 │     if (objective.verification.length) {
162 │       out.push("**Verifier attempts:**", "");
163 │       for (const a of objective.verification) out.push(`- #${a.n} \`${a.command}\` → ${a.status} on ${a.inputs.slice(0, 12)}${a.failedCheck ? ` (${a.failedCheck})` : ""}`);
164 │       out.push("");
165 │     }
166 │   }
167 │   if (session.verificationConfigAttempts?.length) {
168 │     out.push("**Verification configuration edits (tests, CI, build):**", "");
169 │     for (const a of session.verificationConfigAttempts) out.push(`- ${a.timestamp} ${a.decision} \`${a.tool}\` ${a.path} (${a.class}${a.role ? `, ${a.role}` : ""})`);
170 │     out.push("", `Record integrity: ${describeChain(verifyChain(session.verificationConfigAttempts))}.`);
171 │     out.push("");
172 │   }
173 │   if (session.commandRuleDecisions?.length) {
174 │     out.push("**Operator command rules (which rule decided a shell command):**", "");
175 │     for (const d of session.commandRuleDecisions) out.push(`- ${d.timestamp} ${d.effect}: \`${d.command}\` by rule ${d.rule} (${d.decision} \`${d.prefix}\`${d.justification ? `: ${d.justification}` : ""})`);
176 │     out.push("");
177 │   }
178 │   if (session.activePlan?.length) {
179 │     out.push("**Plan (the agent's roadmap; requirement states above are authoritative):**", "");
180 │     for (const p of session.activePlan) out.push(`- [${p.status}] ${p.name}${p.detail ? ` — ${p.detail}` : ""}`);
181 │     out.push("");
182 │   }
183 │   out.push("---", "");
184 │   const render = (m: ChatMessage, archivedMessage: boolean) => {
185 │     if (m.role === "system") {
186 │       const text = contentText(m);
187 │       if (!text.startsWith(SUMMARY_PREFIX)) return;
188 │       out.push("### Context summary (earlier messages replaced by compaction)", "", "```json", text.slice(text.indexOf("\n") + 1), "```", "", "---", "");
189 │       return;
190 │     }
191 │     const who = m.role === "user" ? "User" : m.role === "assistant" ? "Nexus" : `Tool (${m.name})`;
192 │     const calls = m.tool_calls?.length ? `\n\n_tool calls: ${m.tool_calls.map((c) => `${c.function.name} [${c.id}]`).join(", ")}_` : "";
193 │     const ref = m.role === "tool" && m.tool_call_id ? ` [${m.tool_call_id}]` : "";
194 │     out.push(`### ${archivedMessage ? "(archived) " : ""}${who}${ref}`, "", `${contentText(m)}${calls}`, "", "---", "");
195 │   };
196 │   if (archived.length) {
197 │     out.push("## Archived history (replaced in context by summaries)", "");
198 │     for (const m of archived) render(m, true);
199 │   }
200 │   out.push("## Conversation context", "");
201 │   for (const m of session.messages) render(m, false);
202 │   return out.join("\n");
203 │ }

