 30 │ export function historyCompleteness(session: SessionData, archived: { messages: ChatMessage[]; unreadableLines: number }): HistoryCompleteness {
 31 │   const summaries = session.messages.filter((m, i) => i > 0 && m.role === "system" && contentText(m).startsWith(SUMMARY_PREFIX)).length;
 32 │   const recorded = session.history;
 33 │   const compactions = recorded?.compactions ?? (summaries > 0 ? summaries : 0);
 34 │   const compacted = compactions > 0 || summaries > 0;
 35 │   const complete: HistoryCompleteness["complete"] = recorded ? !compacted : compacted ? false : "unknown";
 36 │   const archivedMessages = recorded?.archivedMessages ?? 0;
