269 │ /** The records of a flight log in file order; `null` marks a non-empty line that is not a JSON object. */
270 │ function parseFlightLines(text: string): Array<FlightEvent | null> {
271 │   const records: Array<FlightEvent | null> = [];
272 │   for (const line of text.split("\n")) {
273 │     if (line.trim().length === 0) continue;
274 │     try {
275 │       const parsed = JSON.parse(line);
276 │       records.push(parsed && typeof parsed === "object" && !Array.isArray(parsed) ? (parsed as FlightEvent) : null);
277 │     } catch {
278 │       records.push(null);
279 │     }
280 │   }
281 │   return records;
282 │ }
