284 │ /**
285 │  * Replay player for deterministic flight logs.
286 │  */
287 │ export class FlightPlayer {
288 │   public static listFlights(workspace: string): FlightManifest[] {
289 │     const flightsDir = path.join(path.resolve(workspace), ".nexus", "flights");
290 │     if (!fs.existsSync(flightsDir)) return [];
291 │ 
292 │     const files = fs.readdirSync(flightsDir).filter((f) => f.endsWith(".flightlog"));
293 │     const manifests: FlightManifest[] = [];
294 │ 
295 │     for (const file of files) {
296 │       const fullPath = path.join(flightsDir, file);
297 │       try {
298 │         const firstLine = fs.readFileSync(fullPath, "utf-8").split("\n")[0];
299 │         if (firstLine) {
300 │           const parsed = JSON.parse(firstLine);
301 │           if (parsed.type === "session_start" && parsed.payload) {
302 │             manifests.push(parsed.payload as FlightManifest);
303 │           }
304 │         }
305 │       } catch {}
306 │     }
307 │ 
308 │     return manifests.sort((a, b) => b.recordedAt.localeCompare(a.recordedAt));
309 │   }
310 │ 
311 │   public static loadFlight(workspace: string, flightIdOrPath: string): { manifest: FlightManifest; events: FlightEvent[]; integrity: FlightIntegrity } {
312 │     let fullPath = flightIdOrPath;
313 │     if (!fs.existsSync(fullPath)) {
314 │       const candidate = path.join(path.resolve(workspace), ".nexus", "flights", flightIdOrPath.endsWith(".flightlog") ? flightIdOrPath : `${flightIdOrPath}.flightlog`);
315 │       if (fs.existsSync(candidate)) {
316 │         fullPath = candidate;
317 │       } else {
318 │         throw new Error(`Flight log not found: ${flightIdOrPath}`);
319 │       }
320 │     }
321 │ 
322 │     const records = parseFlightLines(fs.readFileSync(fullPath, "utf-8"));
323 │     const events: FlightEvent[] = [];
324 │     let manifest: FlightManifest | undefined;
325 │ 
326 │     for (const ev of records) {
327 │       // An unreadable line is still left out of the replay, as before; the chain verdict reports it.
328 │       if (!ev) continue;
329 │       events.push(ev);
330 │       if (ev.type === "session_start" && !manifest) {
331 │         manifest = ev.payload as FlightManifest;
332 │       }
333 │     }
334 │     const last = records[records.length - 1];
335 │     const integrity: FlightIntegrity = { chain: verifyChain(records), closed: Boolean(last && last.type === "session_end") };
336 │ 
337 │     if (!manifest) {
338 │       manifest = {
339 │         flightId: path.basename(fullPath, ".flightlog"),
340 │         recordedAt: new Date().toISOString(),
341 │         workspace,
342 │         model: "unknown",
343 │         endpoint: "unknown",
344 │         status: "completed",
345 │       };
346 │     }
347 │ 
348 │     return { manifest, events, integrity };
349 │   }
350 │ 
351 │   /** One line for the operator: what reading the log back established about it. */
352 │   public static describeIntegrity(integrity: FlightIntegrity): string {
353 │     const chain = describeChain(integrity.chain);
354 │     if (integrity.chain.status !== "intact" || integrity.chain.records === 0) return chain;
355 │     return integrity.closed
356 │       ? `${chain}, closed by its session end`
357 │       : `${chain}, not closed: no session end (still recording, stopped early, or records are missing from the end)`;
358 │   }
359 │ 
360 │   public static async replay(
361 │     events: FlightEvent[],
362 │     onEvent?: (e: FlightEvent) => void,
363 │     delayMs: number = 0,
364 │   ): Promise<void> {
365 │     for (const ev of events) {
366 │       if (onEvent) {
367 │         onEvent(ev);
368 │       }
369 │       if (delayMs > 0) {
370 │         await new Promise((resolve) => setTimeout(resolve, delayMs));
371 │       }
372 │     }
373 │   }
374 │ }

