export function getAuditMaxBytes(): number {
  const envVal = process.env.NEXUS_AUDIT_MAX_BYTES;
  if (envVal) {
    const parsed = parseInt(envVal, 10);
    if (!isNaN(parsed) && parsed > 0) return parsed;
