127 │     if (diffPath) record.diffPath = diffPath;
128 │   }
129 │ 
130 │   get(evidence: string): EvidenceRecord | undefined {
131 │     return this.records.get(evidence);
132 │   }
133 │ }
134 │ 
135 │ /** What the operator is told when they decline a call (the model is told its own sentence, in the tool result). */
136 │ export const DENIED_BY_OPERATOR = "Denied by you";
137 │ 
138 │ export type ReceiptRow = [string, string];
139 │ 
140 │ export interface ReceiptSection {
141 │   title: string;
142 │   rows: ReceiptRow[];
143 │   /** Why the section is empty, or a footnote. */
144 │   note?: string;
145 │ }
146 │ 
147 │ /** The last turn as reported in `turn.result`. */
148 │ export interface LastTurn {
149 │   heading: string;
150 │   turn: TurnResult;
151 │ }
152 │ 
153 │ export function receiptSections(last: LastTurn | null, receipt: ValidationReceipt | null, objective?: ObjectiveLedger): ReceiptSection[] {
154 │   return [turnSection(last), ...(objective ? [requirementSection(objective)] : []), verifierSection(last?.turn ?? null), validationSection(receipt)];
155 │ }
156 │ 
157 │ /** Requirement-level state of the operator's objective; a completed plan phase never stands in for these rows. */
158 │ function requirementSection(ledger: ObjectiveLedger): ReceiptSection {
159 │   const rows: ReceiptRow[] = requirementRows(ledger).map(([id, value]) => [id, clean(value)]);
160 │   const outcome = ledger.outcome;
161 │   if (outcome) {
162 │     rows.push(["objective", outcome.status.toUpperCase()]);
163 │     if (outcome.failedCheck) rows.push(["failed check", clean(outcome.failedCheck)]);
164 │     if (outcome.nextAction) rows.push(["next action", clean(outcome.nextAction)]);
165 │   }
166 │   const steering = ledger.steering.filter((s) => s.status !== "cancelled");
167 │   if (steering.length) rows.push(["steering", `${steering.filter((s) => s.status === "applied").length} applied, ${steering.filter((s) => s.status === "queued").length} queued`]);
168 │   if (ledger.scopeChanges.length) rows.push(["scope changes", ledger.scopeChanges.map((c) => `${c.requirement} ${c.from}->${c.to}`).join(", ")]);
169 │   const note = rows.length ? undefined : "The objective is a single request; no separate acceptance requirements were listed.";
170 │   return { title: "Requirements", rows, ...(note ? { note } : {}) };
171 │ }
172 │ 
173 │ /** Receipts can be read back from state files written by older or damaged runs, so any field may be missing. */
174 │ function row(rows: ReceiptRow[], label: string, value: unknown): void {
175 │   if (value !== null && value !== undefined) rows.push([label, clean(String(value))]);
176 │ }
177 │ 
178 │ function turnSection(last: LastTurn | null): ReceiptSection {
179 │   if (!last) return { title: "Last turn", rows: [], note: "No turn has finished in this session yet." };
180 │   const t = last.turn;
181 │   const rows: ReceiptRow[] = [
182 │     ["result", clean(last.heading)],
183 │     ["execution", t.execution],
184 │     ["outcome", t.outcome],
185 │   ];
186 │   if (t.reason) rows.push(["reason", t.reason]);
187 │   if (t.detail) rows.push(["detail", clean(t.detail)]);
188 │   rows.push(["steps", `${t.steps.used} of ${t.steps.max}${t.steps.limitReached ? " · limit reached" : ""}`]);
189 │   rows.push(["model stop", t.modelStop]);
190 │   if (t.interruption) {
191 │     rows.push(["interrupted", `during ${t.interruption.phase.replace(/_/g, " ")}`]);
192 │     if (t.interruption.outstandingTool) rows.push(["outstanding", clean(t.interruption.outstandingTool)]);
193 │   }
194 │   if (t.inferenceFailure) {
195 │     const failure = t.inferenceFailure;
196 │     rows.push(["inference", `${failure.kind} (${failure.origin}): ${clean(failure.message)}`]);
197 │   }
198 │   if (t.unverifiedChangesPending) rows.push(["pending", "workspace changes that no passing verifier run covers"]);
199 │   rows.push(["finished", t.finishedAt]);
200 │   return { title: "Last turn", rows };
201 │ }
202 │ 
203 │ function verifierSection(turn: TurnResult | null): ReceiptSection {
204 │   const v = turn?.verification;
205 │   if (!v) return { title: "Verifier", rows: [], note: turn ? "No verifier ran for this turn." : "Nothing to report until a turn finishes." };
206 │   const rows: ReceiptRow[] = [["status", v.status]];
207 │   if (v.command) rows.push(["command", clean(v.command)]);
208 │   if (v.source) rows.push(["source", v.source]);
209 │   if (v.exitSuccess !== undefined) rows.push(["exit", v.exitSuccess ? "success" : "failure"]);
210 │   if (v.outputSha256) rows.push(["output sha256", v.outputSha256]);
211 │   if (v.candidateId) rows.push(["candidate", v.candidateId]);
212 │   rows.push(["at", v.at]);
213 │   return { title: "Verifier", rows };
214 │ }
215 │ 
216 │ function validationSection(receipt: ValidationReceipt | null): ReceiptSection {
217 │   if (!receipt) {
218 │     return {
219 │       title: "Validation receipt",
220 │       rows: [],
221 │       note: "No validation receipt is active. Authoritative verifier runs (--authoritative-verifier) record one.",
222 │     };
223 │   }
224 │   const rows: ReceiptRow[] = [];
225 │   row(rows, "status", receipt.status);
226 │   row(rows, "receipt", receipt.receiptId);
227 │   row(rows, "command", receipt.verifierCommand);
228 │   row(rows, "exit code", receipt.exitCode);
229 │   row(rows, "stdout sha256", receipt.stdoutHash);
230 │   row(rows, "candidate", receipt.candidateId);
231 │   row(rows, "recorded", receipt.timestamp);
232 │   const deps = receipt.materialDependencies ?? [];
233 │   row(rows, "dependencies", deps.length ? deps.map((d) => `${d.name}=${d.path ? d.versionOrHash.slice(0, 12) : d.versionOrHash}`).join(", ") : "legacy (none recorded)");
234 │   if (receipt.invalidationReason) {
235 │     row(rows, "invalidated", `${receipt.invalidationReason}${receipt.invalidatedAt ? ` (${receipt.invalidatedAt})` : ""}`);
236 │   }
237 │   return { title: "Validation receipt", rows };
238 │ }
239 │ 
240 │ /** The sections as plain text, for clients without the receipt panel. */
241 │ export function receiptText(sections: ReceiptSection[]): string {
242 │   return sections
243 │     .map((s) => [s.title, ...s.rows.map(([label, value]) => `  ${label.padEnd(14)}${value}`), ...(s.note ? [`  ${s.note}`] : [])].join("\n"))
244 │     .join("\n\n");
245 │ }

