  1 │ /**
  2 │  * PF-2: the machine contract of `nexus run`: the JSON document `--json` prints, the process exit codes, and the task
  3 │  * input read from `--input-json` or stdin. The published schema (docs/protocol/run-result-v1.schema.json) is generated
  4 │  * from the types here by scripts/gen_run_result_schema.mjs; docs/USER_MANUAL.md documents the exit codes from the table
  5 │  * below, and test/run_json_contract.test.ts fails when either falls behind.
  6 │  */
  7 │ import fs from "node:fs";
  8 │ import type { TaskExecutionResult } from "./core/app.js";
  9 │ import type { EngineeringOutcome, ExecutionState } from "./core/turn.js";
 10 │ import type { UsageTotals } from "./usage.js";
 11 │ 
 12 │ /**
 13 │  * Version of the document `nexus run --json` prints. Adding an optional member keeps the version; removing or renaming
 14 │  * a member, or changing a member's type or meaning, bumps it. Every change is recorded in
 15 │  * docs/protocol/RUN_RESULT_VERSIONS.json.
 16 │  */
 17 │ export const RUN_RESULT_SCHEMA_VERSION = 1;
 18 │ 
 19 │ /** Printed when the task ran to an ending (whatever the ending): the task result with the contract version first. */
 20 │ export interface RunJsonResult extends TaskExecutionResult {
 21 │   /** Version of this document's schema. Always the first member. */
 22 │   schema_version: typeof RUN_RESULT_SCHEMA_VERSION;
 23 │   /** Cloud provider usage of this process; present only when at least one cloud request was made. */
 24 │   cloudUsage?: UsageTotals;
 25 │ }
 26 │ 
 27 │ /**
 28 │  * Printed instead of a result when the run threw before producing one (for example `--resume` of a task that does not
 29 │  * exist). It has no `turn` and no `exitCode`: read the process exit code.
 30 │  */
 31 │ export interface RunJsonError {
 32 │   /** Version of this document's schema. Always the first member. */
 33 │   schema_version: typeof RUN_RESULT_SCHEMA_VERSION;
 34 │   taskId: string;
 35 │   success: false;
 36 │   status: "failed";
 37 │   prompt: string;
 38 │   output: string;
 39 │   plan: TaskExecutionResult["plan"];
 40 │   milestones: TaskExecutionResult["milestones"];
 41 │   validationReceipts: TaskExecutionResult["validationReceipts"];
 42 │   tokenStats: TaskExecutionResult["tokenStats"];
 43 │   durationMs: number;
 44 │   /** Why the run failed (redacted). */
 45 │   error: string;
 46 │ }
 47 │ 
 48 │ /** The one JSON document `nexus run --json` writes to stdout. A result has `turn`; an error document does not. */
 49 │ export type RunJsonOutput = RunJsonResult | RunJsonError;
 50 │ 
 51 │ /** The document for a finished task: `schema_version` first, every result member unchanged, `cloudUsage` when cloud requests were made. */
 52 │ export function runJsonResult(result: TaskExecutionResult, cloud?: UsageTotals): RunJsonResult {
 53 │   return { schema_version: RUN_RESULT_SCHEMA_VERSION, ...result, ...(cloud?.requests ? { cloudUsage: cloud } : {}) };
 54 │ }
 55 │ 
 56 │ export interface RunExitCode {
 57 │   code: number;
 58 │   name: string;
 59 │   when: string;
 60 │ }
 61 │ 
 62 │ /**
 63 │  * Every exit code of `nexus run`, one row per condition. A code can appear in several rows (2 does): the exit code
 64 │  * alone does not tell those conditions apart, the JSON document does. The "Exit codes" table in docs/USER_MANUAL.md is
 65 │  * this table.
 66 │  */
 67 │ export const RUN_EXIT_CODES = [
 68 │   { code: 0, name: "ok", when: "The task completed and its changes were verified (`VERIFIED`), or it changed nothing that needs verifying (`NOT_REQUIRED`)." },
 69 │   { code: 1, name: "failed", when: "Any other ending: the task failed, was blocked (a question for the operator, a capacity or convergence stop), reached a limit, or completed without establishing a result; or the run threw an error." },
 70 │   { code: 1, name: "missing_prompt", when: "No task was given as an argument and `--resume` was not used (with a terminal on stdin and no `--input-json`)." },
 71 │   { code: 1, name: "option_parse", when: "The command line could not be parsed: an unknown option or an option without its value (the option parser exits before the command runs)." },
 72 │   { code: 2, name: "unverified", when: "The task completed but nothing verifies the change (`UNVERIFIED`), or the tests passed without covering it (`REGRESSION_FREE`)." },
 73 │   { code: 2, name: "usage", when: "A usage error before the run started: an invalid option value or combination, or an invalid, oversized or empty `--input-json` or stdin task." },
 74 │   { code: 2, name: "resume_unavailable", when: "`--resume` found no task in the workspace, or `--fork-session` could not make the copy." },
 75 │   { code: 2, name: "task_not_found", when: "The task named by `--resume <id>` has no saved state." },
 76 │   { code: 130, name: "interrupted", when: "The task was interrupted (SIGINT). A second SIGINT exits at once with this code and may leave no JSON document." },
 77 │ ] as const satisfies readonly RunExitCode[];
 78 │ 
 79 │ export type RunExitName = (typeof RUN_EXIT_CODES)[number]["name"];
 80 │ 
 81 │ export function runExitCode(name: RunExitName): number {
 82 │   return RUN_EXIT_CODES.find((row) => row.name === name)!.code;
 83 │ }
 84 │ 
 85 │ /** The exit-code row of a turn that did not complete, by execution state. A new state does not compile until its row is decided. */
 86 │ export const RUN_EXIT_FOR_EXECUTION: Record<Exclude<ExecutionState, "COMPLETED">, RunExitName> = {
 87 │   INTERRUPTED: "interrupted",
 88 │   FAILED: "failed",
 89 │   BLOCKED: "failed",
 90 │   LIMIT_REACHED: "failed",
 91 │ };
 92 │ 
 93 │ /** The exit-code row of a completed turn, by outcome. A new outcome does not compile until its row is decided. */
 94 │ export const RUN_EXIT_FOR_COMPLETED_OUTCOME: Record<EngineeringOutcome, RunExitName> = {
 95 │   VERIFIED: "ok",
 96 │   NOT_REQUIRED: "ok",
 97 │   UNVERIFIED: "unverified",
 98 │   REGRESSION_FREE: "unverified",
 99 │   NOT_ESTABLISHED: "failed",
100 │ };
101 │ 
102 │ /** The table's row for a turn. `exitCodeForTurn` (core/turn.ts) computes the code itself; a test pins the two together. */
103 │ export function runExitNameForTurn(turn: { execution: ExecutionState; outcome: EngineeringOutcome }): RunExitName {
104 │   return turn.execution === "COMPLETED" ? RUN_EXIT_FOR_COMPLETED_OUTCOME[turn.outcome] : RUN_EXIT_FOR_EXECUTION[turn.execution];
105 │ }
106 │ 
107 │ /** Version of the `--input-json` document. */
108 │ export const RUN_INPUT_SCHEMA_VERSION = 1;
109 │ /** Largest task input accepted from `--input-json` or stdin, in bytes. A larger input is rejected, never truncated. */
110 │ export const RUN_INPUT_MAX_BYTES = 1024 * 1024;
111 │ 
112 │ /** Reads a whole stream as UTF-8 text, refusing more than RUN_INPUT_MAX_BYTES. */
113 │ async function readBounded(stream: AsyncIterable<Buffer | string>, what: string): Promise<string> {
114 │   const chunks: Buffer[] = [];
115 │   let bytes = 0;
116 │   for await (const chunk of stream) {
117 │     const piece = typeof chunk === "string" ? Buffer.from(chunk) : chunk;
118 │     bytes += piece.length;
119 │     if (bytes > RUN_INPUT_MAX_BYTES) throw new Error(`${what} is larger than ${RUN_INPUT_MAX_BYTES} bytes`);
120 │     chunks.push(piece);
121 │   }
122 │   try {
123 │     return new TextDecoder("utf-8", { fatal: true }).decode(Buffer.concat(chunks));
124 │   } catch {
125 │     throw new Error(`${what} is not valid UTF-8`);
126 │   }
127 │ }
128 │ 
129 │ /**
130 │  * The task of an `--input-json` document: `{ "schema_version": 1, "task": "<text>" }`. Only `task` is read. Every other
131 │  * member is ignored, so the document cannot set the approval mode, sandbox, endpoint, credentials or workspace: those
132 │  * stay with the command line and the operator's configuration.
133 │  */
134 │ export function parseRunInput(text: string): string {
135 │   let doc: unknown;
136 │   try {
137 │     doc = JSON.parse(text);
138 │   } catch {
139 │     throw new Error("--input-json: the input is not valid JSON");
140 │   }
141 │   if (doc === null || typeof doc !== "object" || Array.isArray(doc)) throw new Error("--input-json: the input must be a JSON object");
142 │   const { schema_version: version, task } = doc as Record<string, unknown>;
143 │   if (version !== RUN_INPUT_SCHEMA_VERSION) {
144 │     throw new Error(`--input-json: ${version === undefined ? "schema_version is missing" : `unsupported schema_version ${JSON.stringify(version)}`} (this nexus reads schema_version ${RUN_INPUT_SCHEMA_VERSION})`);
145 │   }
146 │   if (typeof task !== "string" || !task.trim()) throw new Error('--input-json: "task" must be a non-empty string');
147 │   return task.trim();
148 │ }
149 │ 
150 │ export interface RunTaskSource {
151 │   /** The task given as command-line arguments, joined and trimmed; empty when none. */
152 │   prompt: string;
153 │   /** The value of `--input-json`: a file path, or `-` for stdin. */
154 │   inputJson?: string;
155 │   /** `--resume` or `--fork-session` is in effect: a missing task is allowed and stdin is not read for one. */
156 │   resuming: boolean;
157 │   stdin: AsyncIterable<Buffer | string> & { isTTY?: boolean };
158 │ }
159 │ 
160 │ /**
161 │  * The task text of a run. An argument wins when it is the only source; `--input-json` supplies it from a document;
162 │  * otherwise, when not resuming and stdin is not a terminal, stdin is the task as plain text. Throws a usage error
163 │  * (exit code `usage`) for a conflict or an invalid input. Returns "" when no source applies (a terminal on stdin, or a
164 │  * resume): the caller keeps its existing handling of a missing task.
165 │  */
166 │ export async function resolveRunTask(source: RunTaskSource): Promise<string> {
167 │   if (source.inputJson !== undefined) {
168 │     if (source.prompt) throw new Error("give the task either as an argument or with --input-json, not both");
169 │     if (source.inputJson === "-") return parseRunInput(await readBounded(source.stdin, "--input-json: the input"));
170 │     let text: string;
171 │     try {
172 │       text = await readBounded(fs.createReadStream(source.inputJson), "--input-json: the input");
173 │     } catch (err: any) {
174 │       if (!err?.code) throw err;
175 │       throw new Error(`--input-json: cannot read ${source.inputJson} (${err.code})`);
176 │     }
177 │     return parseRunInput(text);
178 │   }
179 │   if (source.prompt || source.resuming || source.stdin.isTTY) return source.prompt;
180 │   const task = (await readBounded(source.stdin, "the task on stdin")).trim();
181 │   if (!task) throw new Error("no task: stdin was empty (give the task as an argument, on stdin, or with --input-json)");
182 │   return task;
183 │ }
