48 │ /**
49 │  * The version-decision rule (the same as the protocol ledger's, with the key `schema_version`): the newest ledger entry
50 │  * must name the current schema version and the hash of the checked-in schema. Returns what is wrong, or undefined.
51 │  */
52 │ export function resultLedgerProblem(schemaText, ledger, version, versionConst) {
53 │   if (!Array.isArray(ledger) || ledger.length === 0) return "the ledger has no entries";
54 │   const last = ledger[ledger.length - 1];
55 │   if (last.schema_version !== version) return `the newest ledger entry is for schema_version ${last.schema_version}, but ${versionConst} is ${version}`;
56 │   const hash = sha256(schemaText);
57 │   if (last.schemaSha256 !== hash) return `the newest ledger entry records schema ${last.schemaSha256}, but the schema is ${hash}: add an entry that records the version decision`;
58 │   return undefined;
59 │ }
60 │ 
61 │ /** The command line of a generator: write the schema, or with `--check` exit 1 when the schema or its ledger is stale. */
62 │ export function resultSchemaMain({ script, generate, schemaFile, ledgerFile, ledgerProblem }) {
63 │   const { version, text } = generate();
64 │   const file = schemaFile(version);
65 │   const shown = path.relative(repo, file).split(path.sep).join("/");
66 │   const ledgerShown = path.relative(repo, ledgerFile).split(path.sep).join("/");
67 │   if (process.argv.includes("--check")) {
68 │     const current = fs.existsSync(file) ? fs.readFileSync(file, "utf8") : undefined;
69 │     if (current !== text) {
70 │       console.error(`${shown} is ${current === undefined ? "missing" : "out of date"}: run \`node cli/scripts/${script}.mjs\`, then record the version decision in ${ledgerShown}`);
71 │       process.exit(1);
72 │     }
73 │     const problem = ledgerProblem(current, fs.existsSync(ledgerFile) ? JSON.parse(fs.readFileSync(ledgerFile, "utf8")) : [], version);
74 │     if (problem) {
75 │       console.error(`${ledgerShown}: ${problem}`);
76 │       process.exit(1);
77 │     }
78 │     console.log(`${shown} is current`);
79 │   } else {
80 │     fs.mkdirSync(path.dirname(file), { recursive: true });
81 │     fs.writeFileSync(file, text);
82 │     console.log(`wrote ${shown} (sha256 ${sha256(text)})`);
83 │   }
84 │ }
