  1 │ /**
  2 │  * VR-1: the machine contract of `nexus verify`: the verdicts, the process exit codes and the JSON document `--json`
  3 │  * prints (the same document `--receipt <file>` writes). docs/USER_MANUAL.md documents the exit codes from the table
  4 │  * below and test/verify_command.test.ts fails when the manual falls behind. The published schema
  5 │  * (docs/protocol/verify-result-v1.schema.json) is generated from the types here by scripts/gen_verify_result_schema.mjs,
  6 │  * so they are plain data (no functions, no index signatures); test/verify_schema.test.ts fails when it falls behind.
  7 │  */
  8 │ import type { EngineeringOutcome, TypecheckEvidence, VerificationEvidence } from "./core/turn.js";
  9 │ import type { TypecheckBaselineRecord } from "./core/typecheck_evidence.js";
 10 │ import type { EvidenceOutcomeReason } from "./core/verification_outcome.js";
 11 │ import type { VerificationClass, VerificationMode } from "./security.js";
 12 │ import type { TypecheckMode } from "./tester.js";
 13 │ 
 14 │ /**
 15 │  * Version of the document `nexus verify --json` prints. Adding an optional member keeps the version; removing or
 16 │  * renaming a member, or changing a member's type or meaning, bumps it. Every change is recorded in
 17 │  * docs/protocol/VERIFY_RESULT_VERSIONS.json.
 18 │  */
 19 │ export const VERIFY_RESULT_SCHEMA_VERSION = 1;
 20 │ 
 21 │ /**
 22 │  * VERIFIED: evidence independent of the change shows it. REGRESSION_FREE: the tests pass, which shows only that nothing
 23 │  * they cover broke. UNVERIFIED: nothing was established (see `outcome` and `reason`). BLOCKED: a person must decide
 24 │  * before anything is run or concluded.
 25 │  */
 26 │ export type VerifyVerdict = "VERIFIED" | "REGRESSION_FREE" | "UNVERIFIED" | "BLOCKED";
 27 │ 
 28 │ /** Why the verdict is not VERIFIED: the outcome ladder's reasons, and the ones only `nexus verify` gives. */
 29 │ export type VerifyReason =
 30 │   | EvidenceOutcomeReason
 31 │   /** Base and head are the same tree. */
 32 │   | "NOTHING_TO_VERIFY"
 33 │   /** The head changed the files that define the verifier, so the verifier was not run on the head. */
 34 │   | "VERIFIER_DEFINITION_CHANGED"
 35 │   /** The verifier is an inline program whose definition cannot be captured, so it was not run on the head. */
 36 │   | "VERIFIER_DEFINITION_NOT_CAPTURED"
 37 │   /** An enforced type-check failed on the head: an error in a changed file, or one the base did not have. */
 38 │   | "TYPECHECK_FAILED"
 39 │   /** An enforced type-check did not finish within the deadline. */
 40 │   | "TYPECHECK_TIMED_OUT"
 41 │   /** An enforced type-check could not be run: its tool is not installed, or its configuration is one this checker cannot run. */
 42 │   | "TYPECHECK_UNAVAILABLE"
 43 │   /** Type-checking is enforced and a project of the base tree has no counterpart in the head, so no evidence exists for it. */
 44 │   | "TYPECHECK_NOT_RUN"
 45 │   /** The change edits verification files (or weakens a test) and the edit was not approved, or the base's policy refuses such edits. */
 46 │   | "VERIFICATION_EDIT_BLOCKED"
 47 │   /** Not every changed file could be classified, so the guard's findings are not the whole picture. */
 48 │   | "GUARD_INCOMPLETE"
 49 │   /** A verifier discovered in the repository needs the operator's approval. */
 50 │   | "VERIFIER_NOT_APPROVED"
 51 │   /** Git was refused in the checkout (a planted or rewritten `.git`). */
 52 │   | "UNTRUSTED_CHECKOUT"
 53 │   /** A tree is larger than the limits, or reading it took longer than allowed. */
 54 │   | "TREE_LIMIT_EXCEEDED"
 55 │   /** A tree holds something that is not materialised (a submodule). */
 56 │   | "UNSUPPORTED_TREE"
 57 │   /** `nexus verify` itself failed; nothing was established. */
 58 │   | "INTERNAL_ERROR";
 59 │ 
 60 │ export interface VerifyExitCode {
 61 │   code: number;
 62 │   name: string;
 63 │   when: string;
 64 │ }
 65 │ 
 66 │ /**
 67 │  * Every exit code of `nexus verify`, one row per condition (the same row shape as RUN_EXIT_CODES). A code can appear in
 68 │  * several rows: the exit code alone does not tell those conditions apart, the JSON document does. The "Exit codes"
 69 │  * table in docs/USER_MANUAL.md is this table. Unlike `nexus run`, code 3 exists (a person must decide) and an empty
 70 │  * change is not 0 (the caller chose the base).
 71 │  */
 72 │ export const VERIFY_EXIT_CODES = [
 73 │   { code: 0, name: "verified", when: "`VERIFIED`: the change is shown by evidence independent of it." },
 74 │   { code: 1, name: "failed", when: "`UNVERIFIED` with outcome `NOT_ESTABLISHED`: the verifier failed or timed out on the head, an enforced type-check failed, timed out or could not be run, or the head changed the verifier's own definition so it was not run." },
 75 │   { code: 1, name: "error", when: "`UNVERIFIED` with reason `INTERNAL_ERROR`: `nexus verify` itself could not finish, so nothing was established." },
 76 │   { code: 1, name: "option_parse", when: "The command line could not be parsed: an unknown option or an option without its value (the option parser exits before the command runs; no JSON document)." },
 77 │   { code: 2, name: "unverified", when: "`REGRESSION_FREE` (the tests pass without showing the change), or `UNVERIFIED` because there is no verifier, no test executed, base and head are the same tree, or an enforced type-check project of the base has no counterpart in the head." },
 78 │   { code: 2, name: "usage", when: "A usage error: not a Git working tree, a base or head that does not name a commit, or an invalid option value or combination." },
 79 │   { code: 3, name: "blocked", when: "`BLOCKED`: a person must decide. The discovered verifier is not approved, the change edits verification files or weakens a test without approval, the changed files could not all be classified, the checkout is not trusted, or a tree exceeds the limits or holds a submodule." },
 80 │   { code: 130, name: "interrupted", when: "Interrupted (SIGINT or SIGTERM). The signal is acted on when the running verifier process ends; a second signal exits at once and may leave no JSON document." },
 81 │ ] as const satisfies readonly VerifyExitCode[];
 82 │ 
 83 │ export type VerifyExitName = (typeof VERIFY_EXIT_CODES)[number]["name"];
 84 │ 
 85 │ export function verifyExitCode(name: VerifyExitName): number {
 86 │   return VERIFY_EXIT_CODES.find((row) => row.name === name)!.code;
 87 │ }
 88 │ 
 89 │ /** The verdict and exit-code row of every reason. A new reason does not compile until both are decided. */
 90 │ export const VERIFY_REASONS: Record<VerifyReason, { verdict: Exclude<VerifyVerdict, "VERIFIED">; exit: VerifyExitName }> = {
 91 │   REGRESSION_FREE: { verdict: "REGRESSION_FREE", exit: "unverified" },
 92 │   NO_APPLICABLE_VERIFIER: { verdict: "UNVERIFIED", exit: "unverified" },
 93 │   NO_TESTS_EXECUTED: { verdict: "UNVERIFIED", exit: "unverified" },
 94 │   VERIFICATION_NOT_RUN: { verdict: "UNVERIFIED", exit: "unverified" },
 95 │   NOTHING_TO_VERIFY: { verdict: "UNVERIFIED", exit: "unverified" },
 96 │   TYPECHECK_NOT_RUN: { verdict: "UNVERIFIED", exit: "unverified" },
 97 │   TYPECHECK_FAILED: { verdict: "UNVERIFIED", exit: "failed" },
 98 │   TYPECHECK_TIMED_OUT: { verdict: "UNVERIFIED", exit: "failed" },
 99 │   TYPECHECK_UNAVAILABLE: { verdict: "UNVERIFIED", exit: "failed" },
100 │   VERIFIER_FAILED: { verdict: "UNVERIFIED", exit: "failed" },
101 │   VERIFIER_TIMED_OUT: { verdict: "UNVERIFIED", exit: "failed" },
102 │   VERIFIER_DEFINITION_CHANGED: { verdict: "UNVERIFIED", exit: "failed" },
103 │   VERIFIER_DEFINITION_NOT_CAPTURED: { verdict: "UNVERIFIED", exit: "failed" },
104 │   INTERNAL_ERROR: { verdict: "UNVERIFIED", exit: "error" },
105 │   VERIFIER_NOT_APPROVED: { verdict: "BLOCKED", exit: "blocked" },
106 │   VERIFICATION_EDIT_BLOCKED: { verdict: "BLOCKED", exit: "blocked" },
107 │   GUARD_INCOMPLETE: { verdict: "BLOCKED", exit: "blocked" },
108 │   UNTRUSTED_CHECKOUT: { verdict: "BLOCKED", exit: "blocked" },
109 │   TREE_LIMIT_EXCEEDED: { verdict: "BLOCKED", exit: "blocked" },
110 │   UNSUPPORTED_TREE: { verdict: "BLOCKED", exit: "blocked" },
111 │ };
112 │ 
113 │ /** The verdict for a reason; no reason is VERIFIED. */
114 │ export function verifyVerdictFor(reason: VerifyReason | undefined): VerifyVerdict {
115 │   return reason === undefined ? "VERIFIED" : VERIFY_REASONS[reason].verdict;
116 │ }
117 │ 
118 │ /** The exit-code row for a reason; no reason is VERIFIED. */
119 │ export function verifyExitNameFor(reason: VerifyReason | undefined): VerifyExitName {
120 │   return reason === undefined ? "verified" : VERIFY_REASONS[reason].exit;
121 │ }
