123 │ /** One side of the comparison. */
124 │ export interface VerifyTreeRef {
125 │   /** What the operator named: a ref, or "(working tree)". */
126 │   ref: string;
127 │   /** The commit; null for the working tree, which has none. */
128 │   commit: string | null;
129 │   /** The Git tree that was materialised and verified. For the working tree: tracked and untracked files that are not ignored, as `git add -A` would stage them (Nexus's own `.nexus` state left out). */
130 │   tree: string;
131 │   workingTree: boolean;
132 │ }
133 │ 
134 │ export interface VerifyVerifierRecord {
135 │   command: string;
136 │   /** `configured`: the operator's `--verifier`. `discovered`: selected from the files of the base tree. */
137 │   source: "configured" | "discovered";
138 │   /** The base-tree file that justifies a discovered verifier, or "configured". */
139 │   evidence: string;
140 │   /** sha256 of the command and the script body it resolves to in the base tree. */
141 │   digest: string;
142 │   /** How it was approved: it is the operator's own command, `--yes`, a matching `--approve-verifier` digest, or not at all. */
143 │   approval: "operator_command" | "yes" | "digest" | "none";
144 │   /** The script body the command resolves to in the base tree (capped), when there is one. */
145 │   script?: string;
146 │ }
147 │ 
148 │ export interface VerifyRunRecord {
149 │   /** `base_tests_on_head`: the test files as they were on the base, run against the head's code. */
150 │   phase: "base" | "head" | "base_tests_on_head";
151 │   passed: boolean;
152 │   timedOut: boolean;
153 │   /** Null when the process was killed or never started. */
154 │   exitCode: number | null;
155 │   /** The output shows at least one test that ran. */
156 │   executedTests: boolean;
157 │   outputSha256: string;
158 │   outputTruncated: boolean;
159 │   durationMs: number;
160 │   /** The end of the output of a run that did not pass: repository-controlled text, redacted and capped. */
161 │   outputTail?: string;
162 │ }
163 │ 
164 │ export interface VerifyBaselineSummary {
165 │   /** The verifier failed on the base tree. */
166 │   failed: boolean;
167 │   /** The base run can serve as the "failed before" half: it failed, by itself, with tests that ran. */
168 │   usable: boolean;
169 │   /** Test files captured from the base tree; null when one was too large to capture. */
170 │   testFiles: number | null;
171 │   /** The files that define the verifier were captured from the base tree. */
172 │   verifierDefinitionBound: boolean;
173 │   /** Why they could not be captured. */
174 │   verifierUnbindableReason?: string;
175 │ }
176 │ 
177 │ /** An ingredient of the verdict that this version does not run. Later versions add statuses and members. */
178 │ export interface VerifyIngredient {
179 │   status: "NOT_RUN";
180 │   detail?: string;
181 │ }
182 │ 
183 │ /**
184 │  * The project type-checks. The evidence of every project (tool, configuration, status, counts, tool hash) is in
185 │  * `verification.typecheck.projects`; this is the summary and the base side.
186 │  */
187 │ export interface VerifyTypecheck {
188 │   /**
189 │    * NOT_RUN: the verifier did not pass on the head (or verification stopped earlier), so no type-check was run.
190 │    * Otherwise the combined status of the head's projects, as in `verification.typecheck.status`.
191 │    */
192 │   status: "NOT_RUN" | TypecheckEvidence["status"];
193 │   /** `enforce`: a failing check lowers the verdict. `record`: recorded only (your own `--verifier`). `off`: disabled by NEXUS_TYPECHECK. */
194 │   mode?: TypecheckMode;
195 │   detail?: string;
196 │   /** The same projects on the base tree: what a "new" error on the head is measured against. */
197 │   baseline?: TypecheckBaselineRecord[];
198 │   /** Projects of the base tree that the head no longer has (tool and configuration path). */
199 │   missingFromHead?: string[];
200 │ }
201 │ 
202 │ /** One changed file that decides how the change is verified. */
203 │ export interface VerifyGuardFinding {
204 │   path: string;
205 │   class: VerificationClass;
206 │   kind: "added" | "modified" | "deleted";
207 │   /** For a test file: what the edit removed (a heuristic over the text). Absent when nothing was detected. */
208 │   weakening?: string[];
209 │   /** The edit needs `--approve-verification-edit <path>`: a verification configuration file, or a weakened test. */
210 │   requiresApproval: boolean;
211 │   /** The operator approved this path. Approval lets the verdict be reported; it never makes the change VERIFIED. */
212 │   approved: boolean;
213 │ }
214 │ 
215 │ /** The verification-file guard: which changed files define or weaken the verification, under the BASE tree's policy. */
216 │ export interface VerifyGuard {
217 │   /** NOT_RUN: verification stopped before the change was read. CLEAR: nothing waits for a decision. BLOCKED: a finding does, or the scan is incomplete. */
218 │   status: "NOT_RUN" | "CLEAR" | "BLOCKED";
219 │   /** `approve`: a finding that requires approval blocks until approved. `block`: it blocks, and approval is not accepted. */
220 │   mode?: VerificationMode;
221 │   /** `base_tree`: the base tree's `.nexus-security.json` (it can only tighten). `default`: the base tree has none. The head's is never read. */
222 │   policySource?: "base_tree" | "default";
223 │   findings: VerifyGuardFinding[];
224 │   /** False when a changed file could not be classified (unreadable, too large, or too many findings). */
225 │   complete: boolean;
226 │   detail?: string;
227 │ }
228 │ 
229 │ export interface VerifyLimits {
230 │   /** Deadline of each verifier run, and of the type-checks of each side, in seconds. */
231 │   timeoutSecs: number;
232 │   maxTreeFiles: number;
233 │   maxTreeBytes: number;
234 │ }
235 │ 
236 │ /** Printed when verification reached a verdict, whatever the verdict. It is also the receipt. */
237 │ export interface VerifyJsonResult {
238 │   /** Version of this document's schema. Always the first member. */
239 │   schema_version: typeof VERIFY_RESULT_SCHEMA_VERSION;
240 │   verdict: VerifyVerdict;
241 │   outcome: Exclude<EngineeringOutcome, "NOT_REQUIRED">;
242 │   /** Absent only when the verdict is VERIFIED. */
243 │   reason?: VerifyReason;
244 │   detail?: string;
245 │   /** The process exit code. */
246 │   exitCode: number;
247 │   /** Absent when the checkout was refused before anything was resolved. */
248 │   base?: VerifyTreeRef;
249 │   head?: VerifyTreeRef;
250 │   /** Paths that differ between base and head (at most 200 are listed). */
251 │   changedFiles: string[];
252 │   changedFileCount: number;
253 │   /** Absent when no verifier applies. */
254 │   verifier?: VerifyVerifierRecord;
255 │   /** The operator-declared deliverable files. */
256 │   deliverables: string[];
257 │   /** The paths given with `--approve-verification-edit`. */
258 │   approvedVerificationEdits: string[];
259 │   /** Every verifier process that ran, in order. */
260 │   runs: VerifyRunRecord[];
261 │   baseline?: VerifyBaselineSummary;
262 │   /** The evidence the outcome was derived from. */
263 │   verification?: VerificationEvidence;
264 │   typecheck: VerifyTypecheck;
