 2 │ // gen_verify_result_schema.mjs for `nexus verify --json`): one root type and one version constant in one contract
 3 │ // source, written with the `SchemaBuilder` of gen_protocol_schema.mjs, and a ledger keyed by `schema_version`.
 4 │ import fs from "node:fs";
 5 │ import path from "node:path";
 6 │ import { fileURLToPath } from "node:url";
 7 │ import { API, SymbolFlags } from "typescript/unstable/sync";
 8 │ import { SchemaBuilder, sha256, sortKeys } from "./gen_protocol_schema.mjs";
 9 │ 
10 │ export const cli = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
11 │ export const repo = path.resolve(cli, "..");
12 │ 
13 │ /**
14 │  * The schema text for `rootType` as `source` (relative to cli/) declares it now, and the value of `versionConst`.
15 │  * `script` names the generator in errors; `title(version)` and `description` are the schema's annotations.
16 │  */
17 │ export function generateResultSchema({ script, source, rootType, versionConst, title, description }) {
18 │   const api = new API({ cwd: cli });
19 │   try {
20 │     const snapshot = api.updateSnapshot({ openProjects: [path.join(cli, "tsconfig.json")] });
21 │     const project = snapshot.getProjects()[0];
22 │     if (!project) throw new Error(`${script}: cli/tsconfig.json did not load as a project`);
23 │     const checker = project.checker;
24 │     const sourceAt = { document: path.join(cli, source), position: 0 };
25 │     const versionSymbol = checker.resolveName(versionConst, SymbolFlags.Value, sourceAt);
26 │     const version = versionSymbol && checker.getTypeOfSymbol(versionSymbol)?.value;
27 │     if (!Number.isInteger(version)) throw new Error(`${script}: ${versionConst} is not an integer literal in ${source}`);
28 │     const rootSymbol = checker.resolveName(rootType, SymbolFlags.TypeAlias, sourceAt);
29 │     if (!rootSymbol) throw new Error(`${script}: ${rootType} is not declared in ${source}`);
30 │     const root = checker.getDeclaredTypeOfSymbol(rootSymbol);
31 │     if (root.isErrorType()) throw new Error(`${script}: ${rootType} did not resolve`);
32 │ 
33 │     const builder = new SchemaBuilder(checker);
34 │     const rootSchema = builder.schemaOf(root, rootType);
35 │     const schema = {
36 │       $schema: "https://json-schema.org/draft/2020-12/schema",
37 │       title: title(version),
38 │       description,
39 │       ...rootSchema,
40 │       $defs: sortKeys(builder.defs),
41 │     };
42 │     return { version, text: `${JSON.stringify(schema, null, 2)}\n` };
43 │   } finally {
44 │     api.close();
45 │   }
46 │ }
