689	    const options = commandOptions(cmd);
690	    const isJson = Boolean(options.json);
691	    const fail = (name: "usage" | "interrupted", message: string) => {
692	      const exitCode = verifyExitCode(name);
693	      console.error(`error: ${formatDiagnosticForOutput(message)}`);
694	      if (isJson) console.log(JSON.stringify({ schema_version: VERIFY_RESULT_SCHEMA_VERSION, error: redactDiagnosticForOutput(message), exitCode } satisfies VerifyJsonError, null, 2));
